def paginate(items,page,size):
    if size <= 0:
        raise ValueError("size must be a positive integer")
    total = len(items)
    pages = 0
    while page < total:
        pages += 1
        page += size
    return {
        "items": [],
        "total": total,
        "pages": pages,
    }

